import { Component, OnInit, signal } from '@angular/core';
import { Router, RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { CommonModule, DatePipe } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Auth } from '../../services/auth';
import { OrganizacionesService } from '../../services/organizaciones';
import { CatalogosService } from '../../services/catalogos';
import { BadgeAlertasService } from '../../services/badge-alertas';

@Component({
  selector: 'app-organizaciones-lista',
  standalone: true,
  imports: [FormsModule, RouterLink, CommonModule, DatePipe],
  templateUrl: './organizaciones-lista.html',
  styleUrl: './organizaciones-lista.css'
})
export class OrganizacionesLista implements OnInit {
  usuario: any;
  sidebarAbierto = signal(false);
  organizaciones = signal<any[]>([]);
  cargando = signal(true);
  tipos = signal<any[]>([]);
  zonas = signal<any[]>([]);
  filtroTipo = signal<number | null>(null);
  filtroZona = signal<number | null>(null);
  filtroCategoria = signal('todos');
  busqueda = signal('');
  colFiltros = signal<{ [key: string]: string }>({
    nombre: '', tipo: '', zona: '', colonia: '',
    estado: '', presidente: '', telefono: ''
  });
  colDropdownAbierto = signal<string | null>(null);

  // Fila seleccionada para certificado
  filaSeleccionada = signal<any | null>(null);
  generandoCert = signal(false);

  private timeoutBusqueda: any;

  constructor(
    private auth: Auth,
    private router: Router,
    private orgService: OrganizacionesService,
    private catalogosService: CatalogosService,
    private http: HttpClient,
    public badgeAlertas: BadgeAlertasService
  ) {
    this.usuario = this.auth.getUsuario();
  }

  ngOnInit() {
    this.badgeAlertas.cargar();
    this.catalogosService.tipos().subscribe({ next: (res) => this.tipos.set(Array.isArray(res) ? res : []) });
    this.catalogosService.zonas().subscribe({ next: (res) => this.zonas.set(Array.isArray(res) ? res : []) });
    this.cargar();
  }

  cargar() {
    this.cargando.set(true);
    this.orgService.obtenerReporte({}).subscribe({
      next: (res) => { this.organizaciones.set(res ?? []); this.cargando.set(false); },
      error: () => this.cargando.set(false)
    });
  }

  // ── Filtros por columna ────────────────────────────────────
  abrirDropdownCol(col: string, event: Event) {
    event.stopPropagation();
    this.colDropdownAbierto.set(this.colDropdownAbierto() === col ? null : col);
  }
  cerrarDropdowns() { this.colDropdownAbierto.set(null); }
  setFiltroCol(col: string, valor: string) {
    const actual = { ...this.colFiltros() }; actual[col] = valor;
    this.colFiltros.set(actual); this.colDropdownAbierto.set(null);
  }
  limpiarFiltroCol(col: string) {
    const actual = { ...this.colFiltros() }; actual[col] = '';
    this.colFiltros.set(actual); this.colDropdownAbierto.set(null);
  }
  limpiarTodosFiltrosCol() {
    this.colFiltros.set({ nombre: '', tipo: '', zona: '', colonia: '', estado: '', presidente: '', telefono: '' });
  }
  hayFiltrosCol(): boolean { return Object.values(this.colFiltros()).some(v => v !== ''); }

  organizacionesFiltradas(): any[] {
    return this.aplicarFiltros(this.colFiltros());
  }
  private aplicarFiltros(f: { [key: string]: string }): any[] {
    return this.organizaciones().filter(o => {
      const pres = this.presidente(o);
      if (f['nombre'] && !o.nombre?.toLowerCase().includes(f['nombre'].toLowerCase())) return false;
      if (f['tipo'] && !o.tipo?.nombre?.toLowerCase().includes(f['tipo'].toLowerCase())) return false;
      if (f['zona'] && !o.zona?.nombre?.toLowerCase().includes(f['zona'].toLowerCase())) return false;
      if (f['colonia'] && !(o.colonia_sector || '').toLowerCase().includes(f['colonia'].toLowerCase())) return false;
      if (f['estado'] && !this.textoEstado(o).toLowerCase().includes(f['estado'].toLowerCase())) return false;
      if (f['presidente'] && !(pres?.nombre_completo || '').toLowerCase().includes(f['presidente'].toLowerCase())) return false;
      if (f['telefono'] && !(pres?.telefono_personal || '').toLowerCase().includes(f['telefono'].toLowerCase())) return false;
      return true;
    });
  }
  valoresUnicos(col: string): string[] {
    // Leer el signal explicitamente para que Angular detecte la dependencia
    const filtrosActuales = this.colFiltros();
    // Excluir el filtro de esta columna para mostrar opciones disponibles
    // segun los OTROS filtros activos (filtros en cascada)
    const filtrosSinEstaCol = { ...filtrosActuales, [col]: '' };
    const base = this.aplicarFiltros(filtrosSinEstaCol);
    const set = new Set<string>();
    base.forEach(o => {
      const pres = this.presidente(o);
      let val = '';
      switch (col) {
        case 'nombre':     val = o.nombre || ''; break;
        case 'tipo':       val = o.tipo?.nombre || ''; break;
        case 'zona':       val = o.zona?.nombre || ''; break;
        case 'colonia':    val = o.colonia_sector || ''; break;
        case 'estado':     val = this.textoEstado(o); break;
        case 'presidente': val = pres?.nombre_completo || ''; break;
        case 'telefono':   val = pres?.telefono_personal || ''; break;
      }
      if (val) set.add(val);
    });
    return Array.from(set).sort();
  }

  // ── Selección de fila ──────────────────────────────────────
  seleccionarFila(o: any, event: Event) {
    event.stopPropagation();
    // Si ya está seleccionada, deseleccionar
    if (this.filaSeleccionada()?.id === o.id) {
      this.filaSeleccionada.set(null);
    } else {
      this.filaSeleccionada.set(o);
    }
  }

  deseleccionar() { this.filaSeleccionada.set(null); }

  // Si la org seleccionada tiene presidente registrado = tiene directiva
  tienDirectiva(): boolean {
    const o = this.filaSeleccionada();
    return !!(o && o.directiva && o.directiva.length > 0);
  }

  // ── Imprimir certificado ───────────────────────────────────
  imprimirCertificado() {
    const o = this.filaSeleccionada();
    if (!o) return;
    this.generandoCert.set(true);
    const token = localStorage.getItem('token');
    this.http.get<any>(`http://localhost:5000/api/organizaciones/${o.id}/certificado`, {
      headers: { Authorization: `Bearer ${token}` }
    }).subscribe({
      next: (datos) => {
        this.generandoCert.set(false);
        this.abrirCertificado(datos);
      },
      error: (err) => {
        this.generandoCert.set(false);
        alert(err.error?.msg || 'Error al generar el certificado');
      }
    });
  }

  private abrirCertificado(d: any) {
    const org = d.organizacion;
    const dir: any[] = d.directiva;
    const cfg = d.config;
    const filas = dir.map(m => `<tr><td>${m.cargo?.nombre || ''}</td><td>${m.nombre_completo}</td><td>${m.dni}</td></tr>`).join('');
    const fmtFecha = (s: string) => new Date(s).toLocaleDateString('es-HN', {day:'numeric',month:'long',year:'numeric'});
    const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"/>
<title>Certificado - ${org.nombre}</title>
<style>
@import url("https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400&family=Open+Sans:wght@300;400;600;700&display=swap");
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:"Open Sans",sans-serif;background:#d8d8d8;display:flex;justify-content:center;padding:30px}
.page{width:816px;min-height:1056px;background:#fff;box-shadow:0 8px 36px rgba(0,0,0,.2);display:flex;flex-direction:column}
.top{background:linear-gradient(135deg,#0F2D52,#1A4B8C,#2E75D4);padding:28px 52px 22px;display:flex;align-items:center;gap:18px}
.top img{height:94px;width:auto;filter:drop-shadow(0 3px 6px rgba(0,0,0,.4))}
.top-txt{flex:1;text-align:center}
.top-muni{font-family:"Playfair Display",serif;font-size:26px;color:#fff;letter-spacing:1px}
.top-dpto{font-size:10px;font-weight:600;color:rgba(255,255,255,.75);text-transform:uppercase;letter-spacing:1.2px;margin-top:5px}
.top-ciudad{font-size:9.5px;color:rgba(255,255,255,.5);margin-top:3px}
.filete{height:5px;background:linear-gradient(90deg,#8B6914,#D4A017,#FFD700,#D4A017,#8B6914)}
.body{padding:32px 52px 36px;flex:1;display:flex;flex-direction:column}
.meta{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
.num{font-size:9.5px;color:#aaa;font-family:monospace}
.titulo{text-align:center;flex:1}
.titulo h2{font-family:"Playfair Display",serif;font-size:20px;color:#0F2D52;letter-spacing:2px}
.lineas{display:flex;align-items:center;gap:8px;justify-content:center;margin-top:6px}
.linea{flex:1;height:1px;background:#D4A017;max-width:80px}
.star{color:#D4A017}
.cuerpo{font-size:13px;line-height:1.95;text-align:justify;color:#222;margin-bottom:20px}
.cuerpo strong{color:#0F2D52;font-weight:700}
.tbl-hdr{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.deco{width:28px;height:2px;background:#D4A017}
.tbl-lbl{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#0F2D52}
table{width:100%;border-collapse:collapse;margin-bottom:22px;border:1px solid #DDE4EE}
th{background:#0F2D52;color:#fff;font-size:10.5px;font-weight:700;text-transform:uppercase;padding:9px 14px;text-align:left}
th:first-child{border-left:3px solid #D4A017}
td{padding:8px 14px;font-size:12.5px;border-bottom:1px solid #EEF1F6;color:#222}
tr:nth-child(even) td{background:#F5F8FC}
tr:last-child td{border-bottom:none}
td:first-child{font-weight:700;color:#0F2D52;width:160px;border-left:3px solid transparent}
td:last-child{font-size:11.5px;color:#777;font-family:monospace}
.fechas{display:flex;gap:16px;margin-bottom:22px}
.fecha{flex:1;border-left:4px solid #D4A017;padding:8px 14px;background:#FAFBFD}
.fecha-lbl{font-size:9px;font-weight:700;text-transform:uppercase;color:#999}
.fecha-val{font-size:14.5px;font-weight:700;color:#0F2D52;margin-top:3px;font-family:"Playfair Display",serif}
.pie{font-size:13px;line-height:1.85;text-align:justify;color:#333;margin-bottom:auto}
.firma{margin-top:44px;text-align:center}
.firma-esp{height:54px}
.firma-lin{width:250px;border-top:1px solid #555;margin:0 auto 7px}
.firma-nom{font-family:"Playfair Display",serif;font-size:14px;color:#0F2D52;font-weight:700}
.firma-cargo{font-size:11px;color:#666;margin-top:2px}
.bottom{height:8px;background:linear-gradient(90deg,#8B6914,#D4A017,#FFD700,#D4A017,#8B6914);margin-top:28px}
.btn{position:fixed;top:20px;right:20px;background:#0F2D52;color:#fff;border:none;padding:10px 20px;font-size:14px;border-radius:8px;cursor:pointer;box-shadow:0 4px 12px rgba(0,0,0,.3)}
.btn:hover{background:#1A4B8C}
@media print{body{background:#fff;padding:0}.btn{display:none}.page{box-shadow:none;width:100%}@page{size:letter portrait;margin:0}}
</style></head><body>
<button class="btn" onclick="window.print()">🖨️ Imprimir / Guardar PDF</button>
<div class="page">
  <div class="top">
    <img src="data:image/png;base64," alt="Escudo"/>
    <div class="top-txt">
      <div class="top-muni">${cfg['nombre_institucion']||'Municipalidad de Danlí'}</div>
      <div class="top-dpto">Departamento de Desarrollo Comunitario</div>
      <div class="top-ciudad">Danlí, El Paraíso — Honduras C.A.</div>
    </div>
    <img src="data:image/png;base64," alt="Todos Somos Danlí"/>
  </div>
  <div class="filete"></div>
  <div class="body">
    <div class="meta">
      <span class="num">N° ${d.numeroCertificado}</span>
      <div class="titulo"><h2>C E R T I F I C A C I Ó N</h2>
        <div class="lineas"><div class="linea"></div><span class="star">✦</span><div class="linea"></div></div>
      </div>
      <span class="num">Desarrollo Comunitario</span>
    </div>
    <div class="cuerpo">El suscrito Jefe de la Oficina Municipal de Desarrollo Comunitario de la Municipalidad de Danlí
      <strong>CERTIFICA:</strong> Que en libro de Registro de
      <strong>${org.tipo?.nombre?.toUpperCase()}S TOMO ${org.tomo||'N/A'}, FOLIO ${org.folio||'N/A'}</strong>,
      se encuentra legalmente inscrita la ${org.tipo?.nombre} de
      <strong>${org.nombre?.toUpperCase()}</strong>,
      la cual tendrá una duración de dos años a partir de la fecha de inscripción en el libro de Registro que para tal fin lleva este Departamento.
    </div>
    <div class="tbl-hdr"><div class="deco"></div><div class="tbl-lbl">Miembros de la Junta Directiva</div><div class="deco"></div></div>
    <table><thead><tr><th>Cargo</th><th>Nombre completo</th><th>DNI</th></tr></thead>
      <tbody>${filas}</tbody></table>
    <div class="fechas">
      <div class="fecha"><div class="fecha-lbl">Fecha de Inscripción</div>
        <div class="fecha-val">${fmtFecha(org.fecha_inscripcion)}</div></div>
      <div class="fecha"><div class="fecha-lbl">Vigente Hasta</div>
        <div class="fecha-val">${fmtFecha(org.fecha_vencimiento)}</div></div>
    </div>
    <div class="pie">Se extiende la presente Certificación en la ciudad de Danlí, Departamento de El Paraíso,
      a los <strong>${d.fechaGeneracion}</strong>, para los usos y efectos legales consiguientes.</div>
    <div class="firma"><div class="firma-esp"></div>
      <div class="firma-lin"></div>
      <div class="firma-nom">${cfg['nombre_firmante_pdf']}</div>
      <div class="firma-cargo">${cfg['cargo_firmante_pdf']}</div>
    </div>
  </div>
  <div class="bottom"></div>
</div></body></html>`;
    const v = window.open('', '_blank');
    if (v) { v.document.write(html); v.document.close(); }
  }


  imprimir() { window.print(); }
  presidente(o: any): any { return o.directiva?.[0] ?? null; }
  textoEstado(o: any): string {
    switch (o.estado) {
      case 'activa': return 'Vigente';
      case 'proxima_vencer': return 'Por vencer';
      case 'vencida': return 'Vencida';
      default: return o.estado;
    }
  }
  esAdmin()    { return this.usuario?.id_rol === 1; }
  esConsulta() { return this.usuario?.id_rol === 4; }
  esJefe()     { return this.usuario?.id_rol === 2; }
  esTecnico()  { return this.usuario?.id_rol === 3; }
  nombreRol(): string {
    switch (this.usuario?.id_rol) {
      case 1: return 'Administrador'; case 2: return 'Jefe de Desarrollo Comunitario';
      case 3: return 'Técnico'; case 4: return 'Consulta'; default: return 'Sin rol';
    }
  }
  iniciales(): string { return (this.usuario?.correo || '??').substring(0, 2).toUpperCase(); }
  cerrarSesion() { this.auth.logout(); this.router.navigate(['/login']); }
}
